function normalizeQuranArabic(value=''){return String(value).normalize('NFKD').replace(/[\u064B-\u065F\u0670\u06D6-\u06ED\u06E9\u06E5\u06E6\u06DD-\u06E4\u06E7\u06E8]/g,'').replace(/[ٱأإآ]/g,'ا').replace(/ى/g,'ي').replace(/ؤ/g,'و').replace(/ئ/g,'ي').replace(/ة/g,'ه').replace(/ـ/g,'')}
