function renderBrowse(){const decks=activeDecks(),activeIds=new Set(decks.map(d=>d.id));let filter=browseDeckFilter&&activeIds.has(browseDeckFilter)?browseDeckFilter:'all';browseDeckFilter=null;$('#allCardCount').textContent=state.cards.filter(c=>activeIds.has(c.deckId)).length;const side=$('#browseDecks'),allButton=$('.browser-sidebar [data-filter]');allButton.classList.toggle('active',filter==='all');decks.forEach(d=>{const b=document.createElement('button');b.className='side-item icon-label'+(filter===d.id?' active':'');b.innerHTML=`${icon('layers-3')}${esc(d.name)} <span>${state.cards.filter(c=>c.deckId===d.id).length}</span>`;b.onclick=()=>{filter=d.id;$$('.side-item').forEach(x=>x.classList.remove('active'));b.classList.add('active');renderRows()};side.append(b)});allButton.onclick=()=>{filter='all';$$('.side-item').forEach(x=>x.classList.remove('active'));allButton.classList.add('active');renderRows()};$('#searchCards').oninput=renderRows;$('#cardEditor').onsubmit=e=>{e.preventDefault();const c=state.cards.find(x=>x.id===selectedCard);if(!c)return;c.front=$('#editFront').value;c.back=$('#editBack').value;c.note=$('#editNote').value;c.modified=now();save();renderRows();toast('Carte modifiée')};$('#deleteCardBtn').onclick=()=>{if(!selectedCard||!confirm('Supprimer cette carte ?'))return;state.cards=state.cards.filter(c=>c.id!==selectedCard);selectedCard=null;save();renderRows();showEditor(null)};renderRows();function renderRows(){const q=$('#searchCards').value.toLowerCase(),root=$('#cardRows');root.innerHTML='';state.cards.filter(c=>activeIds.has(c.deckId)&&(filter==='all'||c.deckId===filter)&&(!q||(c.front+' '+c.back+' '+c.note).toLowerCase().includes(q))).forEach(c=>{const r=document.createElement('div');r.className='card-list-row'+(c.id===selectedCard?' active':'');r.innerHTML=`<span>${esc(c.front)}</span><span>${esc(c.back)}</span><span>${dueLabel(c)}</span>`;r.onclick=()=>{selectedCard=c.id;renderRows();showEditor(c)};root.append(r)});refreshIcons()}}
