function drawStats(){const id=$('#statsDeckSelect').value,activeIds=new Set(activeDecks().map(d=>d.id)),rev=state.reviews.filter(r=>id==='all'?activeIds.has(r.deckId):r.deckId===id),cards=state.cards.filter(c=>id==='all'?activeIds.has(c.deckId):c.deckId===id),recent=rev.filter(r=>r.at>now()-30*DAY),correct=recent.filter(r=>r.grade!=='again');$('#statReviews').textContent=fmt(recent.length);$('#statRetention').textContent=recent.length?Math.round(correct.length/recent.length*100)+'%':'—';$('#statStreak').textContent=state.streak+' j';$('#statMature').textContent=cards.filter(c=>c.interval>=21).length;const chart=$('#activityChart');chart.innerHTML='';for(let n=13;n>=0;n--){const d=new Date(today()-n*DAY),key=d.toISOString().slice(0,10),count=rev.filter(r=>new Date(r.at).toISOString().slice(0,10)===key).length,col=document.createElement('div');col.className='chart-col';col.innerHTML=`<i style="height:${Math.min(100,count*12)}%"></i><small>${d.toLocaleDateString('fr-FR',{weekday:'narrow'})}</small>`;chart.append(col)}const groups=[['Nouvelles',cards.filter(c=>status(c)==='new').length,'var(--blue)'],['En apprentissage',cards.filter(c=>status(c)==='learn').length,'var(--orange)'],['À réviser',cards.filter(c=>status(c)==='review').length,'var(--green)'],['Planifiées',cards.filter(c=>status(c)==='scheduled').length,'#8f72d8']],root=$('#stateBars');root.innerHTML='';groups.forEach(([l,n,color])=>{root.insertAdjacentHTML('beforeend',`<div class="state-row"><span>${l}</span><div class="state-track"><i style="width:${cards.length?n/cards.length*100:0}%;background:${color}"></i></div><b>${n}</b></div>`)} )}
function formatStep(m){return m%1440===0?m/1440+'d':m%60===0?m/60+'h':m+'m'}
function parseSteps(value){const steps=value.trim().split(/\s+/).map(x=>{const m=x.match(/^(\d+(?:\.\d+)?)(m|h|d)?$/i);if(!m)return NaN;return+ m[1]*({m:1,h:60,d:1440}[m[2]?.toLowerCase()||'m'])}).filter(Number.isFinite);return steps.length?steps:null}
function renderSettings(){$('#darkMode').checked=state.settings.dark;$('#directionSetting').value=state.settings.direction;$('#dailyLimit').value=state.settings.dailyLimit;$('#learningSteps').value=state.settings.learningSteps.map(formatStep).join(' ');$('#graduatingInterval').value=state.settings.graduatingInterval;$('#easyInterval').value=state.settings.easyInterval;$('#learnAhead').value=state.settings.learnAheadMinutes;$('#darkMode').onchange=e=>{state.settings.dark=e.target.checked;save();document.body.classList.toggle('dark',state.settings.dark)};$('#directionSetting').onchange=e=>{state.settings.direction=e.target.value;save()};$('#dailyLimit').onchange=e=>{state.settings.dailyLimit=Math.max(1,+e.target.value||20);save()};$('#learningSteps').onchange=e=>{const steps=parseSteps(e.target.value);if(!steps){e.target.value=state.settings.learningSteps.map(formatStep).join(' ');return toast('Étapes invalides')}state.settings.learningSteps=steps;save();toast('Étapes enregistrées')};$('#graduatingInterval').onchange=e=>{state.settings.graduatingInterval=Math.max(1,+e.target.value||1);state.settings.easyInterval=Math.max(state.settings.graduatingInterval,state.settings.easyInterval);save();renderSettings()};$('#easyInterval').onchange=e=>{state.settings.easyInterval=Math.max(state.settings.graduatingInterval,+e.target.value||4);save();e.target.value=state.settings.easyInterval};$('#learnAhead').onchange=e=>{state.settings.learnAheadMinutes=Math.max(0,+e.target.value||0);save()};$('#exportDataBtn').onclick=exportData;$('#resetDataBtn').onclick=()=>{if(confirm('Réinitialiser toute la collection ? Cette action est irréversible.')){state=initialState();save();navigate('decks')}}}
