function exportDeck(d){const cards=state.cards.filter(c=>c.deckId===d.id),cardIds=new Set(cards.map(c=>c.id)),reviews=state.reviews.filter(r=>cardIds.has(r.cardId)),payload={version:2,type:'ousbrain-deck',exportedAt:new Date().toISOString(),deck:d,cards,reviews},a=document.createElement('a'),blob=new Blob([JSON.stringify(payload,null,2)],{type:'application/json'}),slug=d.name.normalize('NFD').replace(/[\u0300-\u036f]/g,'').toLowerCase().replace(/[^a-z0-9]+/g,'-').replace(/^-|-$/g,'')||'paquet';a.href=URL.createObjectURL(blob);a.download=`ousbrain-${slug}.json`;a.click();URL.revokeObjectURL(a.href);toast('Paquet exporté')}
