function applyStoredState(nextState){if(!nextState?.decks||!nextState?.cards)throw new Error('Collection cloud invalide');applyingCloudState=true;state=nextState;state.settings={...defaultSettings,...(state.settings||{})};state.cards.forEach(card=>{if(card.learningStep===undefined)card.learningStep=null;if(card.phase===undefined)card.phase=card.interval<1&&card.reps>0?'learning':null});migrateVocabulary();localStorage.setItem('anki2_collection',JSON.stringify(state));applyingCloudState=false;render()}
