async function initializeCloudAuth(){const gate=$('#authGate'),message=$('#authMessage'),form=$('#authForm'),submit=$('#authSubmit');if(!window.supabase?.createClient){message.textContent='Service de connexion indisponible. Vérifiez votre connexion internet.';return}cloudClient=window.supabase.createClient(SUPABASE_URL,SUPABASE_PUBLISHABLE_KEY);form.onsubmit=async event=>{event.preventDefault();submit.disabled=true;message.textContent='Connexion…';const email=$('#authEmail').value.trim(),password=$('#authPassword').value,{data,error}=await cloudClient.auth.signInWithPassword({email,password});if(error){message.textContent='Email ou mot de passe incorrect.';submit.disabled=false;return}try{await activateCloudUser(data.user)}catch(syncError){cloudUser=null;message.textContent='Connexion réussie, mais la synchronisation est indisponible.';console.error('[OusBrain Sync]',syncError)}finally{submit.disabled=false}};$('#logoutBtn').onclick=signOutCloud;$('#mobileLogoutBtn').onclick=signOutCloud;const{data:{session:authSession}}=await cloudClient.auth.getSession();if(authSession?.user){try{await activateCloudUser(authSession.user)}catch(error){cloudUser=null;message.textContent='Impossible de charger la collection cloud.';console.error('[OusBrain Sync]',error)}}else gate.classList.remove('hidden')}
